questionvariables.text:
N: 50+rand(50);
nb: 10+rand(3);
mo: 3+rand(2);
sg: rand([1, 5/4, 3/2]);
ot: rand([[1,1,1],[2,1,1],[1,2,1],[1,1,2],[2,1,2]]);
no: lsum(z, z, ot);
nbody: nb-3;
wb: makelist(float(exp(-(i-mo)^2/(2*sg^2))), i, 1, nbody);
Sb: lsum(z, z, wb);
cb0: makelist(floor(float((N-no)*wb[i]/Sb)), i, 1, nbody);
cb: makelist(if i=mo then cb0[i]+N-no-lsum(z, z, cb0) else cb0[i], i, 1, nbody);
cnt: append(cb, ot);
xc: makelist(6*(i-1)+3, i, 1, nb);
maxc: lmax(cnt);
dots: apply(append, makelist(makelist(xc[i], k, 1, cnt[i]), i, 1, nb));
tm: sum(cnt[i]*xc[i], i, 1, nb)/N;
med: if oddp(N) then dots[(N+1)/2] else (dots[N/2]+dots[N/2+1])/2;
tmd: float(round(10*tm)/10);
medd: float(round(10*med)/10);
nl: length(sublist(dots, lambda([z], z < med)));
nr: length(sublist(dots, lambda([z], z > med)));
ne: N - nl - nr;
[sM, sD]: rand([[4, 6*nb-4], [6*nb-4, 4]]);
ta1: tm;
ta2: med;

feedbackvariables.text:
m: float(ans1);
d: float(ans2);
mvM: is(abs(m-sM) > 0.001);
mvD: is(abs(d-sD) > 0.001);
ok10m: is(mvM and abs(m-tm) <= 0.1*abs(tm));
ok20m: is(mvM and abs(m-tm) <= 0.2*abs(tm));
ok10d: is(mvD and abs(d-med) <= 0.1*abs(med));
ok20d: is(mvD and abs(d-med) <= 0.2*abs(med));
pos: is(mvM and mvD and m > d);
